class Solution {
public:
    int numDifferentIntegers(string word) {
        unordered_set<string> seen;
        int n = word.size();
        int i = 0;
        while (i < n) {
            if (word[i] >= '0' && word[i] <= '9') {
                int j = i;
                while (j < n && word[j] >= '0' && word[j] <= '9') {
                    j++;
                }
                int start = i;
                while (start < j - 1 && word[start] == '0') {
                    start++;
                }
                seen.insert(word.substr(start, j - start));
                i = j;
            } else {
                i++;
            }
        }
        return seen.size();
    }
};
